import { readFileSync, writeFileSync } from 'node:fs'

const read = (f) => readFileSync(new URL('./' + f + '.csv', import.meta.url), 'utf8').trim().split('\n').slice(1).map(line => {
  const out = []; let cur = ''; let q = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++ } else q = false } else cur += ch }
    else if (ch === '"') q = true
    else if (ch === ',') { out.push(cur); cur = '' }
    else cur += ch
  }
  out.push(cur); return out
})

const pretty = (s) => s.split('-').map(w => w ? w[0].toUpperCase() + w.slice(1) : w).join(' ')

const pokemon = read('pokemon')
const typesRows = read('pokemon_types')
const statsRows = read('pokemon_stats')
const speciesRows = read('pokemon_species')
const evoRows = read('pokemon_evolution')
const typeRows = read('types')
const itemRows = read('items')
const namesRows = read('pokemon_species_names')
const flavorRows = read('pokemon_species_flavor_text')

const typeNames = Object.fromEntries(typeRows.map(r => [r[0], pretty(r[1])]))
const itemNames = Object.fromEntries(itemRows.map(r => [r[0], pretty(r[1])]))
const names = {}, genus = {}
for (const r of namesRows) if (r[1] === '9') { names[r[0]] = r[2]; genus[r[0]] = r[3] }
const flavors = {}
for (const r of flavorRows) {
  if (r[2] !== '9') continue
  const txt = r[3].replace(/[\n\f\r]+/g, ' ').replace(/\s+/g, ' ').trim()
  if (txt && !txt.includes('???') && !/^POKéMON?$/i.test(txt)) flavors[r[0]] = txt
}

const bySpecies = {}
for (const r of pokemon) {
  const [id, identifier, speciesId, height, weight, baseExp, order, isDefault] = r
  if (isDefault === '1' && !bySpecies[speciesId]) bySpecies[speciesId] = { id: +id, identifier, height: +height, weight: +weight, baseExp: +baseExp }
}
const typesBy = {}
for (const r of typesRows) (typesBy[r[0]] ||= []).push({ slot: +r[2], name: typeNames[r[1]] })
const statsBy = {}
for (const r of statsRows) (statsBy[r[0]] ||= {})[r[1]] = +r[2]

// pick one evolution condition per evolved species, preferring level conditions
const evoCond = {}
for (const r of evoRows) {
  if (r[3] !== '1' || r[4] !== '1') continue // is_default only
  const target = r[1]
  const cond = {}
  if (r[6]) cond.lvl = +r[6]
  else if (r[5]) cond.item = itemNames[r[5]] || 'Evolution Stone'
  else if (r[16]) cond.friend = true
  else if (r[2] === '2' || r[2] === '3') cond.trade = true
  else cond.special = true
  if (r[13]) cond.happy = +r[13]
  if (r[14]) cond.time = r[14]
  if (!evoCond[target] || (cond.lvl && !evoCond[target].lvl) || (cond.item && !evoCond[target].lvl && !evoCond[target].item)) evoCond[target] = cond
}

const species = {}
for (const r of speciesRows) {
  const id = +r[0]
  species[id] = { gen: +r[2], from: r[3] ? +r[3] : null, capture: +r[9], color: +r[5], shape: +r[6], legendary: r[16] === '1', mythical: r[17] === '1' }
}
const evoTo = {}
for (const [id, cond] of Object.entries(evoCond)) {
  const from = species[id]?.from
  if (!from) continue
  ;(evoTo[from] ||= []).push({ id: +id, ...cond })
}

const dex = []
for (let id = 1; id <= 1025; id++) {
  const sp = species[id]
  const pk = bySpecies[id]
  if (!sp || !pk) continue
  const stats = statsBy[pk.id] || {}
  const base = [stats['1'] || 50, stats['2'] || 50, stats['3'] || 50, stats['4'] || 50, stats['5'] || 50, stats['6'] || 50]
  const entry = {
    n: id,
    name: names[id] || pretty(pk.identifier),
    t: (typesBy[pk.id] || []).sort((a, b) => a.slot - b.slot).map(x => x.name),
    s: base,
    g: sp.gen,
    cr: sp.capture,
    h: pk.height / 10,
    w: pk.weight / 10,
    cat: genus[id] || 'Pokémon',
    fl: flavors[id] || '',
    col: sp.color,
    sh: sp.shape,
  }
  if (sp.legendary) entry.le = 1
  if (sp.mythical) entry.my = 1
  if (evoTo[id]) entry.evo = evoTo[id]
  dex.push(entry)
}

const genRanges = {}
for (const e of dex) { (genRanges[e.g] ||= [e.n, e.n]); genRanges[e.g][1] = e.n }

const out = `// Generated from PokeAPI data. ${dex.length} species.\nexport const POKEDEX = ${JSON.stringify(dex)}\nexport const GEN_RANGES = ${JSON.stringify(genRanges)}\nexport const DEX_BY_ID = new Map(POKEDEX.map(p => [p.n, p]))\nexport const DEX_BY_NAME = new Map(POKEDEX.map(p => [p.name.toLowerCase(), p]))\n`
writeFileSync(new URL('../js/data/pokedex.js', import.meta.url), out)
console.log('species', dex.length, 'bytes', out.length, 'gens', genRanges)
console.log(dex.slice(0, 2), dex[1024])

export const clamp = (v, a, b) => v < a ? a : v > b ? b : v
export const lerp = (a, b, t) => a + (b - a) * t
export const smooth = (t) => t * t * (3 - 2 * t)
export const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1)
export const dist2 = (x1, y1, x2, y2) => (x2 - x1) ** 2 + (y2 - y1) ** 2
export const fmt = (n) => n.toLocaleString('en-US')
export const pad = (n, w = 3) => String(n).padStart(w, '0')

export function mulberry32 (a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0
    let t = Math.imul(a ^ a >>> 15, 1 | a)
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t
    return ((t ^ t >>> 14) >>> 0) / 4294967296
  }
}

export function hash2 (x, y, seed = 0) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 1442695041)
  h = Math.imul(h ^ (h >>> 13), 1274126177)
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296
}

export function hashStr (s) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) }
  return h >>> 0
}

export function valueNoise (x, y, seed = 0) {
  const xi = Math.floor(x), yi = Math.floor(y)
  const xf = smooth(x - xi), yf = smooth(y - yi)
  const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed)
  const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed)
  return lerp(lerp(a, b, xf), lerp(c, d, xf), yf)
}

export function fbm (x, y, seed = 0, oct = 4) {
  let v = 0, amp = .5, f = 1, tot = 0
  for (let i = 0; i < oct; i++) { v += valueNoise(x * f, y * f, seed + i * 131) * amp; tot += amp; amp *= .5; f *= 2 }
  return v / tot
}

export function shade (hex, amt) {
  const c = hex.replace('#', '')
  const n = parseInt(c.length === 3 ? c.split('').map(x => x + x).join('') : c, 16)
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255
  r = clamp(Math.round(r + amt), 0, 255); g = clamp(Math.round(g + amt), 0, 255); b = clamp(Math.round(b + amt), 0, 255)
  return `rgb(${r},${g},${b})`
}

export function hexAlpha (hex, a) {
  const c = hex.replace('#', '')
  const n = parseInt(c.length === 3 ? c.split('').map(x => x + x).join('') : c, 16)
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`
}

export function pickWeighted (list, rng = Math.random) {
  let total = 0
  for (const it of list) total += it.w ?? 1
  let r = rng() * total
  for (const it of list) { r -= it.w ?? 1; if (r <= 0) return it }
  return list[list.length - 1]
}

export function shuffle (arr, rng = Math.random) {
  for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1));[arr[i], arr[j]] = [arr[j], arr[i]] }
  return arr
}

export function titleCase (s) { return s.replace(/\b\w/g, c => c.toUpperCase()) }

export function timeString (minutes) {
  const h = Math.floor(minutes / 60) % 24, m = Math.floor(minutes % 60)
  const ampm = h < 12 ? 'AM' : 'PM'
  return `${((h + 11) % 12) + 1}:${String(m).padStart(2, '0')} ${ampm}`
}

export function niceTime (sec) {
  const h = Math.floor(sec / 3600), m = Math.floor(sec / 60) % 60
  return h ? `${h}h ${m}m` : `${m}m`
}

export const isTouch = () => matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window

import { POKEDEX, DEX_BY_ID } from '../data/pokedex.js'
import { mulberry32, fbm, hash2, clamp, pickWeighted } from '../core/utils.js'
import { GYMS, CHAMPION } from '../data/gyms.js'

export const TILE = 32
export const MAP_W = 192
export const MAP_H = 192

export const T = {
  DEEP: 0, WATER: 1, SAND: 2, GRASS: 3, TALL: 4, FLOWER: 5, FOREST: 6, SNOW: 7, ICE: 8,
  ASH: 9, LAVA: 10, PATH: 11, PLAZA: 12, BRIDGE: 13, ROCKY: 14, MARSH: 15, DIRT: 16,
}
export const SOLID_TILES = new Set([T.DEEP, T.WATER, T.LAVA])
export const TILE_NAMES = ['Deep Water','Water','Sand','Grass','Tall Grass','Flowers','Forest','Snow','Ice','Ash','Lava','Path','Plaza','Bridge','Rocky Ground','Marsh','Dirt']

export const TOWNS = [
  { id:'willowbrook', name:'Willowbrook Town', x:96, y:96, r:11, biome:'meadow', color:'#e9c46a', desc:'The heart of the region. Professor Willow\'s lab and the Champion\'s tower stand here.' },
  { id:'goldleaf', name:'Goldleaf Village', x:34, y:100, r:8, biome:'meadow', color:'#57b94c', desc:'A quiet village of gardeners and beekeepers, home of the Bloom Gym.' },
  { id:'frosthollow', name:'Frosthollow', x:92, y:26, r:8, biome:'snow', color:'#63cfd4', desc:'A snug alpine hamlet beneath the aurora, home of the Frost Gym.' },
  { id:'emberfall', name:'Emberfall', x:158, y:80, r:8, biome:'volcano', color:'#ef7d32', desc:'A forge town on the rim of the caldera, home of the Ember Gym.' },
  { id:'tidecrest', name:'Tidecrest', x:112, y:166, r:8, biome:'lake', color:'#4f8fe8', desc:'A breezy harbor where the tide sings, home of the Tide Gym.' },
  { id:'stormwatch', name:'Stormwatch', x:158, y:34, r:8, biome:'mountain', color:'#f2c744', desc:'A wind-battered lookout above the clouds, home of the Spark Gym.' },
  { id:'dunebloom', name:'Dunebloom', x:32, y:158, r:8, biome:'desert', color:'#c9a54a', desc:'An oasis market at the desert\'s edge, home of the Terra Gym.' },
