.title-wrap { position: relative; z-index: 3; width: min(920px, 94vw); text-align: center; padding: 20px 0 90px; }
.title-badge {
  display: inline-block; font-size: 10px; font-weight: 900; letter-spacing: 2.2px; color: #ffe6a8;
  border: 1px solid rgba(255, 224, 150, .4); background: rgba(20, 20, 35, .4); border-radius: 99px;
  padding: 7px 14px; margin-bottom: 18px; backdrop-filter: blur(6px);
}
.logo {
  margin: 0; font-family: 'Press Start 2P', monospace; font-size: clamp(34px, 8.2vw, 84px); line-height: 1.04;
  letter-spacing: 2px; filter: drop-shadow(0 6px 0 #5a3a10) drop-shadow(0 14px 30px rgba(0,0,0,.45));
}
.logo-poke { color: #ffe6a0; -webkit-text-stroke: 2px #3a2a10; text-shadow: 0 0 30px rgba(255, 220, 130, .35); }
.logo-verse { color: #77f0dc; -webkit-text-stroke: 2px #123a3a; }
.logo-online {
  display: flex; align-items: center; justify-content: center; gap: 14px;
  font-family: 'Press Start 2P', monospace; font-size: clamp(11px, 1.7vw, 18px); letter-spacing: 8px;
  color: #ffd777; margin: 14px auto 0;
}
.logo-online::before, .logo-online::after { content: ''; height: 2px; width: min(120px, 14vw); background: linear-gradient(90deg, transparent, #ffd777); }
.logo-online::after { background: linear-gradient(90deg, #ffd777, transparent); }
.tagline { font-size: clamp(15px, 2vw, 19px); color: #f2e9d8; font-weight: 700; margin: 18px 0 22px; text-shadow: 0 2px 12px rgba(0,0,0,.4); }
.tagline em { color: #ffe6a0; font-style: normal; }
.title-card {
  width: min(560px, 100%); margin: 0 auto; padding: 22px 24px;
  background: rgba(12, 17, 32, .78); border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 22px; box-shadow: 0 30px 80px rgba(0,0,0,.5); backdrop-filter: blur(18px);
  text-align: left;
}
.title-field { margin-bottom: 14px; }
.title-field label { display: block; font-size: 10px; font-weight: 900; letter-spacing: 1.6px; color: #b7c3dd; margin-bottom: 7px; }
.title-field input {
  width: 100%; padding: 12px 14px; border-radius: 11px; border: 1px solid rgba(255,255,255,.16);
  background: rgba(255,255,255,.06); font-size: 16px; font-weight: 700; color: #fff;
}
.title-field input:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(244,201,93,.15); }
.swatches { display: flex; gap: 9px; }
.swatch {
  width: 34px; height: 34px; border-radius: 50%; background: var(--c);
  border: 2px solid rgba(255,255,255,.22); transition: transform .15s, border-color .15s;
}
.swatch:hover { transform: scale(1.1); }
.swatch.active { border-color: #fff; box-shadow: 0 0 0 3px rgba(255,255,255,.18); transform: scale(1.08); }
.title-actions { display: flex; gap: 10px; margin-top: 6px; }
.title-actions .btn { flex: 1; }
.server-status { margin-top: 14px; font-size: 11.5px; color: #9fadc8; text-align: center; }
.server-status b { color: #8ff5c4; }
.live-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: #4be38b; box-shadow: 0 0 8px #4be38b; margin-right: 5px; animation: blink 2s infinite; }
@keyframes blink { 0%,100% { opacity: 1 } 50% { opacity: .35 } }
.starter-showcase { position: absolute; left: 50%; bottom: -68px; transform: translateX(-50%); width: min(900px, 100vw); height: 110px; pointer-events: none; }
.starter-float { position: absolute; width: 84px; height: 84px; image-rendering: pixelated; filter: drop-shadow(0 8px 10px rgba(0,0,0,.4)); animation: bob 4s ease-in-out infinite; opacity: .95; }
.s1 { left: 2%; bottom: 0; animation-delay: -1s; }
.s2 { left: 14%; bottom: 22px; animation-delay: -2.4s; width: 76px; }
.s3 { right: 12%; bottom: 26px; animation-delay: -.6s; width: 78px; }
.s4 { right: 1%; bottom: 4px; animation-delay: -3s; width: 70px; }
@keyframes bob { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-12px) } }
.title-foot { position: absolute; bottom: -34px; left: 0; right: 0; font-size: 10px; color: rgba(255,255,255,.55); }
@media (max-height: 780px) {
  .title-wrap { padding-bottom: 30px; transform: scale(.92); }
  .starter-showcase { display: none; }
  .title-foot { display: none; }
}

/* ================= LOADING ================= */
#loading { position: absolute; inset: 0; z-index: 90; background: #080c17; display: grid; place-items: center; }
.loading-inner { text-align: center; width: min(420px, 84vw); }
.pokeball-spinner { width: 72px; height: 72px; margin: 0 auto 24px; border-radius: 50%; position: relative; background: linear-gradient(#ff6b6b 0 48%, #1a1f2e 48% 52%, #f5f7fb 52%); border: 4px solid #1a1f2e; animation: spinBall 1.6s cubic-bezier(.6,.1,.4,.9) infinite; box-shadow: 0 0 40px rgba(255, 107, 107, .25); }
.pokeball-spinner::after { content: ''; position: absolute; inset: 0; margin: auto; width: 22px; height: 22px; background: #f5f7fb; border: 4px solid #1a1f2e; border-radius: 50%; }
.pokeball-spinner i { position: absolute; inset: 0; margin: auto; width: 8px; height: 8px; background: #1a1f2e; border-radius: 50%; z-index: 2; }
@keyframes spinBall { 0% { transform: rotate(0) } 55% { transform: rotate(380deg) } 70%,100% { transform: rotate(360deg) } }
.loading-title { font-family: 'Press Start 2P', monospace; font-size: 15px; color: var(--gold); margin-bottom: 20px; }
.loading-bar { height: 6px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; }
.loading-bar span { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold), var(--teal)); border-radius: 99px; transition: width .25s; }
.loading-tip { margin-top: 16px; color: var(--muted); font-size: 12.5px; }

/* ================= HUD ================= */
#hud { position: absolute; inset: 0; pointer-events: none; z-index: 10; }
#hud > * { pointer-events: auto; }
.hud-top { position: absolute; top: calc(14px + var(--safe-t)); left: 14px; right: 14px; display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; pointer-events: none; }
.hud-top > * { pointer-events: auto; }
.player-card { display: flex; gap: 12px; padding: 10px 14px 10px 10px; border-radius: 16px; min-width: 258px; }
.avatar-frame { position: relative; width: 64px; height: 72px; border-radius: 12px; background: radial-gradient(circle at 50% 30%, #3b4f7a, #1a2439); border: 1px solid var(--line); overflow: hidden; flex: none; }
.avatar-frame canvas { width: 100%; height: 100%; }
.lvl-badge { position: absolute; bottom: 3px; left: 50%; transform: translateX(-50%); background: rgba(8,12,23,.85); border: 1px solid var(--line-strong); color: var(--gold); font-size: 9px; font-weight: 900; padding: 1px 6px; border-radius: 6px; white-space: nowrap; }
.pc-info { flex: 1; min-width: 0; }
.pc-row { display: flex; align-items: center; gap: 6px; }
.pc-name { font-weight: 900; font-size: 15px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 130px; }
.pc-online { color: #4be38b; font-size: 9px; }
.pc-sub { font-size: 10.5px; color: var(--muted); margin: 1px 0 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 165px; }
.pc-money { display: flex; align-items: center; gap: 4px; font-size: 12px; }
.pc-money b { color: var(--gold-2); font-weight: 900; }
.coin { color: var(--gold); font-size: 11px; }
.badge-row { display: inline-flex; gap: 3px; margin-left: 6px; }
.badge-dot { width: 13px; height: 13px; border-radius: 50%; background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.14); font-size: 8px; display: grid; place-items: center; color: transparent; }
.badge-dot.earned { background: var(--bc); border-color: #fff8; color: #1a1305; box-shadow: 0 0 8px var(--bc); }
.xp-bar { height: 4px; border-radius: 99px; background: rgba(255,255,255,.09); margin-top: 5px; overflow: hidden; }
.xp-bar span { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--teal), #8ff5c4); border-radius: 99px; transition: width .4s; }

.quest-card { width: 292px; padding: 12px 14px; border-radius: 16px; }
.qc-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 5px; }
.qc-label { font-size: 9px; font-weight: 900; letter-spacing: 1.4px; color: var(--gold); }
.qc-title { font-weight: 900; font-size: 14px; }
.qc-desc { font-size: 11.5px; color: var(--muted); line-height: 1.35; margin-top: 2px; }
.qc-progress { height: 4px; background: rgba(255,255,255,.09); border-radius: 99px; margin: 8px 0 5px; overflow: hidden; }
.qc-progress span { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--gold), #ffe6a0); transition: width .4s; }
.qc-hint { font-size: 10.5px; color: var(--gold-2); font-weight: 700; }
.quest-card.collapsed .qc-desc, .quest-card.collapsed .qc-progress, .quest-card.collapsed .qc-hint { display: none; }

.map-card { width: 184px; padding: 8px; border-radius: 16px; }
.mc-head { display: flex; justify-content: space-between; align-items: center; font-size: 10px; color: var(--muted); font-weight: 800; padding: 2px 4px 6px; }
.weather-chip { font-size: 9px; color: #bcd4ff; }
#minimap { width: 100%; aspect-ratio: 1; border-radius: 11px; display: block; image-rendering: pixelated; border: 1px solid var(--line); background: #17324a; }
.mc-zone { text-align: center; font-size: 10px; font-weight: 800; color: #cdd9f1; padding: 5px 2px 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.map-open { width: 100%; margin-top: 4px; }

.chat-panel { position: absolute; left: 14px; bottom: calc(84px + var(--safe-b)); width: 328px; border-radius: 16px; overflow: hidden; transition: transform .25s, opacity .25s; }
.chat-head { display: flex; align-items: center; gap: 6px; padding: 8px 11px; font-size: 9.5px; font-weight: 900; letter-spacing: 1.1px; color: #b9c8e6; border-bottom: 1px solid var(--line); }
.chat-head > span:nth-child(1) { flex: 1; }
.chat-online { color: var(--muted); font-size: 9px; letter-spacing: 0; }
.chat-feed { height: 132px; overflow-y: auto; padding: 7px 11px; font-size: 11.5px; line-height: 1.5; display: flex; flex-direction: column; gap: 3px; scroll-behavior: smooth; }
.chat-line b { color: var(--gold-2); font-weight: 800; }
.chat-line.system { color: var(--teal); font-weight: 700; }
.chat-line.system::before { content: '◆ '; opacity: .7; }
.chat-line .ch-tag { font-size: 8px; padding: 0 4px; border-radius: 4px; background: rgba(255,255,255,.1); color: var(--muted); margin-left: 3px; vertical-align: 1px; }
.chat-input { display: flex; border-top: 1px solid var(--line); }
.chat-input input { flex: 1; background: rgba(0,0,0,.18); border: 0; padding: 9px 11px; font-size: 12px; color: var(--text); }
.chat-input input::placeholder { color: var(--dim); }
.mini-send { padding: 0 13px; color: var(--gold); font-size: 15px; font-weight: 900; }
.chat-panel.collapsed .chat-feed, .chat-panel.collapsed .chat-input { display: none; }

.interact-prompt {
  position: absolute; left: 50%; bottom: calc(154px + var(--safe-b)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px; padding: 9px 16px; border-radius: 99px;
  background: rgba(12, 17, 32, .9); border: 1px solid rgba(244, 201, 93, .45);
  box-shadow: 0 8px 30px rgba(0,0,0,.4); font-size: 12.5px; font-weight: 800; white-space: nowrap;
  animation: promptIn .18s ease-out;
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 6px) } to { opacity: 1; transform: translate(-50%, 0) } }
.key { display: grid; place-items: center; min-width: 22px; height: 22px; border-radius: 6px; background: var(--gold); color: #241a05; font-weight: 900; font-size: 11px; }

.hotbar {
  position: absolute; left: 50%; bottom: calc(14px + var(--safe-b)); transform: translateX(-50%);
  display: flex; gap: 6px; padding: 6px; border-radius: 16px;
  background: rgba(12, 17, 32, .82); border: 1px solid var(--line); backdrop-filter: blur(14px);
  box-shadow: var(--shadow);
}
.hot-btn {
  display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 58px; padding: 7px 8px 5px;
  border-radius: 11px; color: var(--muted); font-size: 9.5px; font-weight: 800; transition: background .15s, color .15s, transform .1s;
}
.hot-btn:hover { background: rgba(255,255,255,.07); color: var(--text); }
.hot-btn:active { transform: scale(.96); }
.hb-icon { font-size: 17px; line-height: 1.1; filter: grayscale(.2); }
.hot-btn kbd { margin-top: 1px; }
.hot-btn.pulse { animation: hotPulse 1.6s infinite; color: var(--gold); }
@keyframes hotPulse { 0%,100% { box-shadow: inset 0 0 0 0 rgba(244,201,93,0) } 50% { box-shadow: inset 0 0 0 2px rgba(244,201,93,.4) } }

.toast-stack { position: absolute; top: calc(96px + var(--safe-t)); left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; gap: 7px; align-items: center; pointer-events: none; z-index: 40; }
.toast {
  display: flex; align-items: center; gap: 9px; padding: 9px 16px; border-radius: 11px;
  background: rgba(12, 17, 32, .93); border: 1px solid var(--line-strong); box-shadow: 0 10px 30px rgba(0,0,0,.4);
  font-size: 12.5px; font-weight: 800; animation: toastIn .3s cubic-bezier(.2,1.4,.4,1);
  max-width: min(460px, 90vw);
}
.toast.out { animation: toastOut .3s forwards; }
.toast .t-icon { font-size: 16px; }
.toast.gold { border-color: rgba(244,201,93,.45); color: var(--gold-2); }
.toast.green { border-color: rgba(98,212,122,.4); }
.toast.red { border-color: rgba(255,107,107,.45); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-12px) scale(.94) } to { opacity: 1; transform: none } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px) scale(.96) } }

.pop-layer { position: absolute; inset: 0; pointer-events: none; z-index: 8; overflow: hidden; }
.pop-text { position: absolute; font-weight: 900; font-size: 13px; color: var(--gold-2); text-shadow: 0 2px 8px rgba(0,0,0,.8); animation: popUp 1.1s ease-out forwards; }
@keyframes popUp { from { opacity: 0; transform: translate(-50%, 0) scale(.8) } 20% { opacity: 1; transform: translate(-50%, -10px) scale(1.05) } to { opacity: 0; transform: translate(-50%, -44px) scale(1) } }

/* touch */
#touch-ui { position: absolute; inset: 0; pointer-events: none; }
.joystick { position: absolute; left: calc(20px + env(safe-area-inset-left)); bottom: calc(90px + var(--safe-b)); width: 118px; height: 118px; border-radius: 50%; background: rgba(12,17,32,.42); border: 1.5px solid rgba(255,255,255,.16); pointer-events: auto; backdrop-filter: blur(6px); }
.stick { position: absolute; left: 50%; top: 50%; width: 52px; height: 52px; margin: -26px 0 0 -26px; border-radius: 50%; background: rgba(255,255,255,.24); border: 1.5px solid rgba(255,255,255,.4); box-shadow: 0 4px 18px rgba(0,0,0,.35); }
.touch-actions { position: absolute; right: calc(18px + env(safe-area-inset-right)); bottom: calc(92px + var(--safe-b)); display: flex; align-items: flex-end; gap: 10px; pointer-events: auto; }
.touch-btn { width: 68px; height: 68px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.3), rgba(255,255,255,.1)); border: 1.5px solid rgba(255,255,255,.35); color: #fff; font-weight: 900; font-size: 22px; box-shadow: 0 8px 24px rgba(0,0,0,.35); backdrop-filter: blur(8px); }
.touch-btn.small { width: 48px; height: 48px; font-size: 15px; }
.touch-btn:active { transform: scale(.94); background: rgba(244,201,93,.35); }

/* ================= BATTLE ================= */
#battle {
  position: absolute; inset: 0; z-index: 60; display: flex; flex-direction: column; overflow: hidden;
  background: #0b1020;
}
.battle-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 35%, rgba(120, 180, 255, .18), transparent 60%),
    linear-gradient(180deg, #1c2f4a 0%, #284a54 45%, #365a44 62%, #2a4536 100%);
  transition: background .6s;
}
.battle-bg::after {
  content: ''; position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,.05) 1px, transparent 1px);
  background-size: 26px 26px; opacity: .5;
}
.battle-particles { position: absolute; inset: 0; pointer-events: none; opacity: .5; }
.battle-topbar { position: absolute; top: calc(14px + var(--safe-t)); left: 16px; right: 16px; display: flex; justify-content: space-between; align-items: center; z-index: 5; }
.battle-mode { font-family: 'Press Start 2P', monospace; font-size: 10px; color: #ffdf8e; letter-spacing: 1px; background: rgba(8,12,23,.55); border: 1px solid rgba(255,223,142,.25); border-radius: 8px; padding: 7px 11px; }
.battle-field { position: relative; flex: 1; min-height: 0; }
.platform { position: absolute; border-radius: 50%; background: radial-gradient(ellipse, rgba(255,255,255,.14), rgba(20,40,30,.22) 60%, transparent 72%); }
.enemy-platform { right: 13%; top: 44%; width: 27%; height: 12%; }
.ally-platform { left: 9%; bottom: 6%; width: 30%; height: 13%; }
.battle-sprite { position: absolute; image-rendering: pixelated; filter: drop-shadow(0 16px 18px rgba(0,0,0,.35)); transition: filter .2s; }
.enemy-sprite { right: 15%; top: 13%; width: clamp(130px, 17vw, 230px); height: auto; animation: enemyFloat 3.4s ease-in-out infinite; }
.ally-sprite { left: 10%; bottom: 9%; width: clamp(140px, 19vw, 260px); height: auto; transform: scaleX(-1); animation: allyFloat 3.8s ease-in-out infinite; }
@keyframes enemyFloat { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-8px) } }
@keyframes allyFloat { 0%,100% { transform: scaleX(-1) translateY(0) } 50% { transform: scaleX(-1) translateY(-6px) } }
.battle-sprite.hit { animation: hitShake .35s; filter: brightness(2.2) saturate(.4) drop-shadow(0 16px 18px rgba(0,0,0,.35)); }
@keyframes hitShake { 0%,100% { translate: 0 0 } 20% { translate: -12px 3px } 40% { translate: 9px -4px } 60% { translate: -6px 2px } 80% { translate: 4px -1px } }
.battle-sprite.faint { animation: faintDown .8s forwards; }
@keyframes faintDown { to { transform: translateY(70px) scale(.9); opacity: 0 } }
.battle-sprite.attack-ally { animation: lungeAlly .4s; }
@keyframes lungeAlly { 0%,100% { transform: scaleX(-1) translate(0,0) } 45% { transform: scaleX(-1) translate(48px, -22px) } }
.battle-sprite.attack-enemy { animation: lungeEnemy .4s; }
@keyframes lungeEnemy { 0%,100% { transform: translate(0,0) } 45% { transform: translate(-48px, 22px) } }
.battle-sprite.enter-enemy { animation: enterEnemy .55s ease-out; }
@keyframes enterEnemy { from { transform: translateX(200px); opacity: 0 } to { transform: none; opacity: 1 } }
.battle-sprite.enter-ally { animation: enterAlly .5s ease-out; }
@keyframes enterAlly { from { transform: scaleX(-1) translateX(-200px); opacity: 0 } to { transform: scaleX(-1); opacity: 1 } }
.fx-layer { position: absolute; inset: 0; pointer-events: none; }
.fx-burst { position: absolute; width: 10px; height: 10px; border-radius: 50%; animation: burst .7s ease-out forwards; }
@keyframes burst { to { transform: translate(var(--dx), var(--dy)) scale(.2); opacity: 0 } }

.enemy-panel, .ally-panel {
  position: absolute; width: min(320px, 44vw); padding: 11px 14px; border-radius: 14px; z-index: 6;
  background: linear-gradient(150deg, rgba(18, 27, 48, .94), rgba(9, 14, 26, .9));
  border: 1px solid var(--line-strong); box-shadow: 0 12px 34px rgba(0,0,0,.35);
}
.enemy-panel { left: 16px; top: calc(66px + var(--safe-t)); }
.ally-panel { right: 16px; bottom: calc(240px + var(--safe-b)); }
.bp-name { font-weight: 900; font-size: 16px; display: flex; align-items: center; gap: 6px; }
.bp-gender { font-size: 12px; color: #7fb3ff; }
.bp-level { position: absolute; right: 14px; top: 12px; font-size: 11px; font-weight: 900; color: var(--muted); }
.bp-types { display: flex; gap: 4px; margin: 5px 0 7px; }
.hp-wrap { display: flex; align-items: center; gap: 7px; }
.hp-label { font-size: 8px; font-weight: 900; color: var(--muted); letter-spacing: 1px; }
.hp-bar { flex: 1; height: 7px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; box-shadow: inset 0 1px 2px rgba(0,0,0,.4); }
.hp-bar span { display: block; height: 100%; width: 100%; border-radius: 99px; background: linear-gradient(90deg, #4bd87a, #8ff5a8); transition: width .5s cubic-bezier(.3,.8,.3,1), background .3s; }
.hp-bar span.mid { background: linear-gradient(90deg, #f4c95d, #ffe08a); }
.hp-bar span.low { background: linear-gradient(90deg, #ff5b5b, #ff8a8a); }
.bp-hpnum { text-align: right; font-size: 10px; color: var(--muted); font-weight: 800; margin-top: 3px; }
.bp-status { font-size: 9.5px; font-weight: 900; margin-top: 4px; display: flex; gap: 5px; }
.status-chip { padding: 1px 6px; border-radius: 4px; font-size: 8.5px; letter-spacing: .5px; text-transform: uppercase; }
.st-poison { background: #a44ba5; color: #fff; } .st-burn { background: #ef7d32; color: #fff; }
.st-paralysis { background: #d9b52c; color: #2b2205; } .st-sleep { background: #6b7280; color: #fff; }
.st-freeze { background: #63cfd4; color: #0b2b2d; } .st-confusion { background: #ee5d8c; color: #fff; }
.xp-mini { height: 3px; background: rgba(255,255,255,.1); border-radius: 99px; margin-top: 6px; overflow: hidden; }
.xp-mini span { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--teal), #8ff5c4); transition: width .5s; }

.battle-console {
  position: relative; z-index: 8; padding: 12px 16px calc(14px + var(--safe-b));
  background: linear-gradient(180deg, rgba(10, 15, 28, .94), rgba(6, 10, 20, .98));
  border-top: 1px solid var(--line-strong); display: grid; grid-template-columns: minmax(260px, 1fr) minmax(420px, 1.35fr); gap: 14px;
  min-height: 214px;
}
.battle-log { display: flex; flex-direction: column; justify-content: center; padding: 10px 16px; border-radius: 14px; background: rgba(255,255,255,.035); border: 1px solid var(--line); position: relative; overflow: hidden; }
.log-text { font-size: clamp(14px, 1.4vw, 17px); font-weight: 800; line-height: 1.5; min-height: 52px; }
.battle-message-history { font-size: 11px; color: var(--muted); line-height: 1.45; margin-top: 6px; max-height: 54px; overflow: hidden; }
.battle-commands { display: grid; grid-template-columns: 1fr 108px; gap: 8px; }
.move-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.move-btn {
  position: relative; text-align: left; padding: 9px 11px; border-radius: 11px; border: 1px solid var(--line-strong);
  background: linear-gradient(135deg, rgba(255,255,255,.07), rgba(255,255,255,.02));
  transition: transform .1s, border-color .15s, background .15s; overflow: hidden;
}
.move-btn::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; background: var(--mt); }
.move-btn:hover { background: rgba(255,255,255,.1); border-color: var(--mt); }
.move-btn:active { transform: scale(.98); }
.move-btn:disabled { opacity: .4; }
.mv-name { font-weight: 900; font-size: 13.5px; display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.mv-meta { display: flex; align-items: center; gap: 5px; margin-top: 4px; font-size: 9.5px; color: var(--muted); font-weight: 700; }
.mv-type { padding: 1px 6px; border-radius: 4px; font-size: 8px; font-weight: 900; text-transform: uppercase; letter-spacing: .4px; }
.mv-pp { font-variant-numeric: tabular-nums; }
.mv-eff { font-size: 8.5px; color: var(--gold); font-weight: 900; margin-left: auto; }
.battle-side { display: flex; flex-direction: column; gap: 7px; }
.battle-btn { flex: 1; border-radius: 11px; border: 1px solid var(--line-strong); background: rgba(255,255,255,.06); font-weight: 900; font-size: 12px; color: var(--text); display: flex; align-items: center; justify-content: center; gap: 6px; transition: background .15s; }
.battle-btn:hover { background: rgba(255,255,255,.12); }
.battle-btn.danger { color: #ffb0b0; border-color: rgba(255,107,107,.3); }
.battle-submenu { position: absolute; inset: 12px 16px calc(14px + var(--safe-b)); z-index: 9; background: rgba(8, 13, 25, .97); border: 1px solid var(--line-strong); border-radius: 14px; padding: 12px; overflow-y: auto; }
.sub-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 9px; font-weight: 900; font-size: 13px; }
.sub-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 7px; }
.sub-item { display: flex; align-items: center; gap: 9px; padding: 8px 10px; border-radius: 10px; background: rgba(255,255,255,.05); border: 1px solid var(--line); text-align: left; font-weight: 800; font-size: 12px; }
.sub-item:hover { background: rgba(255,255,255,.1); border-color: var(--line-strong); }
.sub-item .si-icon { font-size: 19px; }
.sub-item .si-sub { font-size: 9.5px; color: var(--muted); font-weight: 700; }
.sub-item:disabled { opacity: .35; }
.catch-anim { position: absolute; inset: 0; display: grid; place-items: center; z-index: 7; pointer-events: none; }
.catch-anim .ball { font-size: 72px; color: #ff5b5b; text-shadow: 0 6px 20px rgba(0,0,0,.5); animation: ballThrow 1s cubic-bezier(.3,.1,.4,1) forwards; }
.catch-anim.shake .ball { animation: ballShake .5s ease-in-out 3; }
@keyframes ballThrow { 0% { transform: translate(30vw, 24vh) scale(.4) rotate(0) } 55% { transform: translate(0, -30px) scale(1.1) rotate(400deg) } 75%,100% { transform: translate(0,0) scale(1) rotate(720deg) } }
@keyframes ballShake { 0%,100% { transform: rotate(0) } 25% { transform: rotate(-18deg) } 75% { transform: rotate(18deg) } }
.catch-stars { position: absolute; top: 38%; font-size: 26px; color: var(--gold); opacity: 0; animation: starsIn .7s 1.2s forwards; }
@keyframes starsIn { to { opacity: 1; transform: translateY(-24px) } }
.battle-flash { position: absolute; inset: 0; pointer-events: none; background: #fff; opacity: 0; z-index: 20; }
.battle-flash.on { animation: flash .25s; }
@keyframes flash { 0% { opacity: .75 } 100% { opacity: 0 } }

/* ================= MODALS ================= */
#modal-layer { position: absolute; inset: 0; z-index: 70; background: rgba(4, 8, 18, .74); backdrop-filter: blur(7px); display: grid; place-items: center; padding: 18px; }
.modal-card {
  width: min(1020px, 96vw); max-height: 90vh; display: flex; flex-direction: column;
  background: linear-gradient(165deg, #172036, #0c1222 60%);
  border: 1px solid var(--line-strong); border-radius: 22px; box-shadow: 0 40px 100px rgba(0,0,0,.6);
  overflow: hidden; animation: modalIn .22s cubic-bezier(.2,.9,.3,1.1);
}
.modal-card.narrow { width: min(640px, 96vw); }
.modal-card.wide { width: min(1120px, 97vw); }
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(.97) } to { opacity: 1; transform: none } }
.modal-head { display: flex; align-items: center; gap: 10px; padding: 15px 18px; border-bottom: 1px solid var(--line); background: rgba(255,255,255,.02); }
.modal-title { font-family: 'Press Start 2P', monospace; font-size: 12px; color: var(--gold); flex: 1; line-height: 1.5; }
.modal-sub { font-size: 11px; color: var(--muted); font-weight: 700; }
.modal-close { width: 32px; height: 32px; border-radius: 9px; background: rgba(255,255,255,.07); border: 1px solid var(--line); color: var(--muted); font-size: 15px; display: grid; place-items: center; }
.modal-close:hover { background: rgba(255,107,107,.18); color: #fff; }
.modal-body { padding: 16px 18px; overflow-y: auto; flex: 1; }
.modal-foot { padding: 12px 18px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; align-items: center; gap: 10px; font-size: 12px; color: var(--muted); }
.tabs { display: flex; gap: 5px; padding: 10px 18px 0; flex-wrap: wrap; }
.tab { padding: 8px 14px; border-radius: 9px 9px 0 0; font-size: 12px; font-weight: 900; color: var(--muted); border: 1px solid transparent; border-bottom: 0; }
.tab.active { background: rgba(255,255,255,.06); border-color: var(--line); color: var(--text); }
.tab:hover { color: var(--text); }

/* party */
.party-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 10px; }
.party-card {
  position: relative; display: flex; gap: 10px; padding: 12px; border-radius: 14px;
  background: linear-gradient(150deg, rgba(255,255,255,.08), rgba(255,255,255,.02));
  border: 1px solid var(--line); overflow: hidden;
}
.party-card::before { content: ''; position: absolute; inset: 0 0 auto; height: 3px; background: var(--tg); }
.party-card.fainted { opacity: .65; filter: grayscale(.5); }
.party-card.active-mon { border-color: var(--gold); box-shadow: 0 0 0 1px rgba(244,201,93,.25); }
.pc-sprite { width: 76px; height: 76px; flex: none; image-rendering: pixelated; align-self: center; filter: drop-shadow(0 6px 8px rgba(0,0,0,.3)); }
.pc-body { flex: 1; min-width: 0; }
.pc-top { display: flex; align-items: center; gap: 6px; }
.pc-mon-name { font-weight: 900; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pc-mon-lv { font-size: 10px; font-weight: 900; color: var(--gold); margin-left: auto; }
.pc-types { display: flex; gap: 4px; margin: 3px 0 5px; }
.pc-hp { height: 5px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; }
.pc-hp span { display: block; height: 100%; background: var(--green); border-radius: 99px; }
.pc-hp span.mid { background: #f4c95d } .pc-hp span.low { background: #ff5b5b }
.pc-hpnum { font-size: 9.5px; color: var(--muted); margin-top: 2px; display: flex; justify-content: space-between; }
.pc-actions { display: flex; gap: 5px; margin-top: 6px; }
.pc-actions button { flex: 1; padding: 4px 6px; border-radius: 6px; background: rgba(255,255,255,.07); border: 1px solid var(--line); font-size: 9.5px; font-weight: 800; color: var(--muted); }
.pc-actions button:hover { color: var(--text); background: rgba(255,255,255,.13); }
.empty-slot { border: 1px dashed rgba(255,255,255,.14); border-radius: 14px; display: grid; place-items: center; min-height: 102px; color: var(--dim); font-size: 11px; font-weight: 800; }
.party-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 12px; flex-wrap: wrap; }
.party-toolbar .hint { font-size: 11px; color: var(--muted); }

/* type chips */
.type-chip { padding: 2px 8px; border-radius: 5px; font-size: 8.5px; font-weight: 900; text-transform: uppercase; letter-spacing: .5px; color: #fff; text-shadow: 0 1px 2px rgba(0,0,0,.35); white-space: nowrap; }

/* dex */
.dex-toolbar { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-bottom: 12px; }
.dex-toolbar input[type=search] { flex: 1; min-width: 140px; padding: 8px 12px; border-radius: 9px; border: 1px solid var(--line); background: rgba(255,255,255,.06); font-size: 12px; }
.gen-pill { padding: 6px 10px; border-radius: 8px; border: 1px solid var(--line); background: rgba(255,255,255,.04); font-size: 10px; font-weight: 900; color: var(--muted); }
.gen-pill.active { background: var(--gold); color: #241a05; border-color: var(--gold); }
.dex-progress { font-size: 11px; font-weight: 800; color: var(--muted); margin-left: auto; }
.dex-progress b { color: var(--gold); }
.dex-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(94px, 1fr)); gap: 7px; }
.dex-entry { position: relative; padding: 8px 6px 6px; border-radius: 11px; background: rgba(255,255,255,.045); border: 1px solid var(--line); text-align: center; transition: transform .12s, background .15s, border-color .15s; overflow: hidden; }
.dex-entry:hover { transform: translateY(-2px); background: rgba(255,255,255,.09); border-color: var(--line-strong); }
.dex-entry.caught { border-color: rgba(244,201,93,.35); background: linear-gradient(160deg, rgba(244,201,93,.13), rgba(255,255,255,.03)); }
.dex-entry.seen:not(.caught) { border-color: rgba(91,157,255,.25); }
.dex-entry img { width: 58px; height: 58px; image-rendering: pixelated; display: block; margin: 0 auto; }
.dex-entry.unseen img { filter: brightness(0) opacity(.22); }
.dex-entry.seen:not(.caught) img { filter: brightness(.55) saturate(.4); }
.dex-num { position: absolute; top: 4px; left: 6px; font-size: 8px; font-weight: 900; color: var(--dim); }
.dex-name { font-size: 9.5px; font-weight: 900; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }
.dex-entry.caught .dex-name { color: var(--gold-2); }
.dex-star { position: absolute; top: 4px; right: 5px; font-size: 8px; color: var(--gold); }
.dex-more { display: block; margin: 14px auto 4px; }
.dex-loading { text-align: center; color: var(--muted); font-size: 11px; padding: 16px; }
.dex-detail { display: flex; gap: 18px; align-items: center; }
.dex-detail img { width: 128px; height: 128px; image-rendering: pixelated; filter: drop-shadow(0 10px 20px rgba(0,0,0,.4)); }
.dex-detail-info { flex: 1; }
.dex-detail-name { font-size: 22px; font-weight: 900; }
.dex-detail-cat { font-size: 11px; color: var(--muted); font-weight: 700; margin-bottom: 7px; }
.dex-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 3px 14px; margin-top: 8px; font-size: 10px; }
.stat-row { display: flex; align-items: center; gap: 6px; }
.stat-row span:first-child { width: 32px; color: var(--muted); font-weight: 800; }
.stat-bar { flex: 1; height: 4px; background: rgba(255,255,255,.1); border-radius: 99px; overflow: hidden; }
.stat-bar i { display: block; height: 100%; background: var(--teal); border-radius: 99px; }
.dex-flavor { font-size: 11.5px; color: #b9c6e2; line-height: 1.5; margin-top: 8px; font-style: italic; }

/* bag & shop */
.bag-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 8px; }
.item-card { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 11px; background: rgba(255,255,255,.045); border: 1px solid var(--line); text-align: left; }
.item-card:hover { background: rgba(255,255,255,.09); }
.item-icon { width: 38px; height: 38px; border-radius: 9px; display: grid; place-items: center; font-size: 20px; background: rgba(255,255,255,.07); border: 1px solid var(--line); flex: none; }
.item-body { flex: 1; min-width: 0; }
.item-name { font-weight: 900; font-size: 12.5px; }
.item-desc { font-size: 9.5px; color: var(--muted); line-height: 1.35; margin-top: 1px; }
.item-count { font-weight: 900; color: var(--gold); font-size: 12px; }
.item-price { font-size: 10px; color: var(--gold-2); font-weight: 800; }
.shop-row { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: 11px; background: rgba(255,255,255,.04); border: 1px solid var(--line); margin-bottom: 6px; }
.shop-row .item-body { flex: 1; }
.shop-buy { padding: 7px 12px; border-radius: 8px; background: rgba(244,201,93,.16); border: 1px solid rgba(244,201,93,.4); color: var(--gold-2); font-weight: 900; font-size: 11px; }
.shop-buy:hover { background: rgba(244,201,93,.28); }
.money-line { font-weight: 900; color: var(--gold-2); }

/* map */
.map-modal-wrap { display: flex; gap: 16px; }
.map-canvas-wrap { position: relative; flex: 1; border-radius: 14px; overflow: hidden; border: 1px solid var(--line); background: #17324a; }
#map-canvas { display: block; width: 100%; height: auto; image-rendering: pixelated; cursor: crosshair; }
.map-side { width: 230px; flex: none; }
.map-legend { font-size: 11px; color: var(--muted); line-height: 2; }
.legend-dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 6px; }
.map-town-list { margin-top: 10px; display: flex; flex-direction: column; gap: 5px; }
.map-town-row { display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 800; padding: 5px 7px; border-radius: 7px; background: rgba(255,255,255,.04); }
.map-town-row small { color: var(--muted); font-weight: 700; margin-left: auto; font-size: 9px; }
.map-town-row .badge-mini { width: 8px; height: 8px; border-radius: 50%; }

/* quests */
.quest-list { display: flex; flex-direction: column; gap: 8px; }
.quest-item { display: flex; gap: 12px; padding: 12px 14px; border-radius: 12px; background: rgba(255,255,255,.045); border: 1px solid var(--line); }
.quest-item.main { border-color: rgba(244,201,93,.35); background: linear-gradient(150deg, rgba(244,201,93,.1), rgba(255,255,255,.02)); }
.quest-icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: rgba(255,255,255,.07); font-size: 17px; flex: none; }
.quest-body { flex: 1; }
.quest-title { font-weight: 900; font-size: 13px; }
.quest-desc { font-size: 11px; color: var(--muted); line-height: 1.4; margin-top: 2px; }
.quest-reward { font-size: 10px; color: var(--gold-2); font-weight: 800; margin-top: 4px; }
.quest-done { font-size: 10px; color: var(--green); font-weight: 900; }
.quest-claim { padding: 5px 10px; border-radius: 7px; background: var(--gold); color: #241a05; font-weight: 900; font-size: 10px; }

/* settings */
.settings-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 11px 2px; border-bottom: 1px solid var(--line); }
.settings-row:last-child { border-bottom: 0; }
.settings-label { font-weight: 800; font-size: 13px; }
.settings-desc { font-size: 10.5px; color: var(--muted); margin-top: 1px; }
input[type=range] { accent-color: var(--gold); width: 160px; }
.switch { width: 42px; height: 24px; border-radius: 99px; background: rgba(255,255,255,.14); position: relative; transition: background .2s; flex: none; }
.switch::after { content: ''; position: absolute; width: 18px; height: 18px; border-radius: 50%; background: #fff; top: 3px; left: 3px; transition: left .2s; }
.switch.on { background: var(--teal); }
.switch.on::after { left: 21px; }
.controls-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 7px; margin-top: 8px; }
.control-row { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--muted); font-weight: 700; }
.control-row kbd { min-width: 24px; }

/* dialogue */
#dialogue { position: absolute; inset: 0; z-index: 65; pointer-events: none; display: flex; align-items: flex-end; justify-content: center; padding: 0 16px calc(96px + var(--safe-b)); }
.dlg-box { pointer-events: auto; width: min(860px, 96vw); display: flex; gap: 14px; padding: 14px; border-radius: 18px; border-color: rgba(244,201,93,.3); animation: dlgIn .22s ease-out; }
@keyframes dlgIn { from { opacity: 0; transform: translateY(16px) } to { opacity: 1; transform: none } }
.dlg-portrait { width: 74px; height: 82px; border-radius: 12px; background: radial-gradient(circle at 50% 35%, #3d4f78, #172036); border: 1px solid var(--line); flex: none; overflow: hidden; }
.dlg-portrait canvas { width: 100%; height: 100%; }
.dlg-main { flex: 1; min-width: 0; }
.dlg-name { font-size: 11px; font-weight: 900; color: var(--gold); letter-spacing: .5px; margin-bottom: 3px; }
.dlg-text { font-size: 14px; font-weight: 700; line-height: 1.5; min-height: 42px; }
.dlg-choices { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; }
.dlg-choice { padding: 8px 14px; border-radius: 9px; background: rgba(255,255,255,.07); border: 1px solid var(--line-strong); font-size: 12px; font-weight: 800; }
.dlg-choice:hover { background: rgba(244,201,93,.16); border-color: var(--gold); color: var(--gold-2); }
.dlg-choice.primary { background: rgba(244,201,93,.18); border-color: rgba(244,201,93,.45); color: var(--gold-2); }

#fade { position: absolute; inset: 0; z-index: 80; background: #05080f; opacity: 0; pointer-events: none; transition: opacity .5s; }
#fade.on { opacity: 1; pointer-events: auto; }

/* starter picker */
.starter-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.starter-card {
  position: relative; padding: 16px; border-radius: 16px; text-align: center; border: 1px solid var(--line);
  background: linear-gradient(170deg, rgba(255,255,255,.08), rgba(255,255,255,.02));
  transition: transform .15s, border-color .15s, box-shadow .15s; cursor: pointer;
}
.starter-card:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.starter-card.selected { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(244,201,93,.25), 0 16px 40px rgba(0,0,0,.3); background: linear-gradient(170deg, rgba(244,201,93,.14), rgba(255,255,255,.02)); }
.starter-card img { width: 110px; height: 110px; image-rendering: pixelated; filter: drop-shadow(0 10px 16px rgba(0,0,0,.35)); animation: bob 4s ease-in-out infinite; }
.starter-name { font-size: 17px; font-weight: 900; margin-top: 4px; }
.starter-card .type-chip { margin: 4px 2px 6px; display: inline-block; }
.starter-desc { font-size: 10.5px; color: var(--muted); line-height: 1.4; min-height: 42px; }
.starter-stats { display: flex; gap: 3px; justify-content: center; margin-top: 8px; }
.starter-stats i { width: 7px; height: 7px; border-radius: 2px; background: rgba(255,255,255,.1); }
.starter-stats i.on { background: var(--teal); }
.starter-check { position: absolute; top: 10px; right: 10px; width: 20px; height: 20px; border-radius: 50%; border: 1px solid var(--line-strong); display: grid; place-items: center; font-size: 11px; color: transparent; }
.starter-card.selected .starter-check { background: var(--gold); border-color: var(--gold); color: #241a05; }

/* evolution overlay */
.evo-overlay { position: absolute; inset: 0; z-index: 85; display: grid; place-items: center; background: radial-gradient(circle, rgba(80, 60, 160, .45), rgba(4, 6, 14, .94)); }
.evo-stage { text-align: center; }
.evo-sprite { width: 200px; height: 200px; image-rendering: pixelated; filter: drop-shadow(0 0 40px rgba(180, 150, 255, .8)) brightness(2); animation: evoPulse 1.2s ease-in-out infinite; }
@keyframes evoPulse { 0%,100% { transform: scale(1); filter: drop-shadow(0 0 30px rgba(180,150,255,.7)) brightness(1.5) } 50% { transform: scale(1.08); filter: drop-shadow(0 0 60px rgba(220,190,255,1)) brightness(3) } }
.evo-text { font-family: 'Press Start 2P', monospace; font-size: 13px; color: #e5d4ff; margin-top: 20px; }
.evo-sub { font-size: 13px; color: #b9a6e8; margin-top: 8px; }

/* misc */
.center { text-align: center; }
.muted { color: var(--muted); }
.row { display: flex; align-items: center; gap: 8px; }
.spacer { flex: 1; }
.pill { padding: 4px 9px; border-radius: 99px; font-size: 10px; font-weight: 900; background: rgba(255,255,255,.07); border: 1px solid var(--line); }
.empty-note { text-align: center; color: var(--dim); font-size: 12px; padding: 30px 10px; }
.section-title { font-size: 10px; font-weight: 900; letter-spacing: 1.3px; color: var(--muted); margin: 14px 0 7px; text-transform: uppercase; }
.warning { color: #ffb3b3; font-size: 11px; }
.good { color: var(--green); }

/* ================= RESPONSIVE ================= */
@media (max-width: 1080px) {
  .quest-card { width: 250px; }
  .chat-panel { width: 290px; }
  .battle-console { grid-template-columns: minmax(220px, 1fr) minmax(360px, 1.4fr); }
}
@media (max-width: 860px) {
  .quest-card { display: none; }
  .map-card { width: 142px; }
  .player-card { min-width: 220px; padding: 8px 11px 8px 8px; }
  .avatar-frame { width: 54px; height: 62px; }
  .chat-panel { width: 260px; }
  .hotbar { gap: 3px; padding: 5px; }
  .hot-btn { min-width: 48px; padding: 6px 6px 4px; font-size: 8.5px; }
  .hb-icon { font-size: 15px; }
  .hot-btn kbd { display: none; }
  .battle-console { grid-template-columns: 1fr; min-height: 0; gap: 8px; padding: 10px 12px calc(10px + var(--safe-b)); }
