    if (this.saveTimer > 18) { this.saveTimer = 0; st.pos = { x: this.player.x / TILE, y: this.player.y / TILE }; st.dir = this.player.dir; st.save() }
    if (Math.random() < dt * .05) this.ui.drawMinimap()
