:root {
  --bg: #080c17;
  --panel: rgba(15, 21, 38, .82);
  --panel-solid: #121a2c;
  --panel-2: rgba(24, 33, 56, .88);
  --line: rgba(160, 190, 255, .14);
  --line-strong: rgba(180, 205, 255, .26);
  --text: #e9effc;
  --muted: #93a2c2;
  --dim: #66728c;
  --gold: #f4c95d;
  --gold-2: #ffdf8e;
  --teal: #58d5c9;
  --red: #ff6b6b;
  --green: #62d47a;
  --blue: #5b9dff;
  --purple: #a97bff;
  --shadow: 0 20px 60px rgba(0, 0, 0, .45);
  --radius: 18px;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font-family: 'Nunito', system-ui, -apple-system, sans-serif;
  overflow: hidden; overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}
button, input, select { font-family: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
input { outline: none; }
.hidden { display: none !important; }
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(150, 175, 220, .25); border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: rgba(150, 175, 220, .4); }

#app { position: fixed; inset: 0; }
#world { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; background: #2c6b48; }
#world-vignette { position: absolute; inset: 0; pointer-events: none; box-shadow: inset 0 0 140px rgba(4, 10, 20, .5); }

.glass {
  background: linear-gradient(160deg, rgba(27, 37, 64, .9), rgba(12, 18, 33, .88));
  border: 1px solid var(--line);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, .05);
  backdrop-filter: blur(14px) saturate(1.1);
  -webkit-backdrop-filter: blur(14px) saturate(1.1);
}
.btn {
  border-radius: 13px; padding: 12px 20px; font-weight: 800; font-size: 15px;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  transition: transform .12s, background .15s, border-color .15s, box-shadow .15s;
}
.btn:active { transform: translateY(1px) scale(.99); }
.btn-primary {
  background: linear-gradient(135deg, #ffd76e, #f0a93d); color: #241a05;
  box-shadow: 0 8px 26px rgba(244, 201, 93, .25), inset 0 1px 0 rgba(255,255,255,.6);
}
.btn-primary:hover { box-shadow: 0 10px 32px rgba(244, 201, 93, .4), inset 0 1px 0 rgba(255,255,255,.6); }
.btn-ghost { background: rgba(255,255,255,.06); border: 1px solid var(--line-strong); color: var(--text); }
.btn-ghost:hover { background: rgba(255,255,255,.11); }
.btn-danger { background: rgba(255, 107, 107, .14); border: 1px solid rgba(255,107,107,.4); color: #ffb3b3; }
.btn-big { padding: 14px 28px; font-size: 16px; min-height: 52px; }
.btn-sm { padding: 8px 13px; font-size: 13px; border-radius: 10px; }
.btn:disabled { opacity: .45; pointer-events: none; }
.mini-btn {
  background: rgba(255,255,255,.07); border: 1px solid var(--line); color: var(--muted);
  border-radius: 8px; font-size: 11px; font-weight: 800; padding: 4px 8px; line-height: 1;
}
.mini-btn:hover { color: var(--text); background: rgba(255,255,255,.13); }
kbd {
  font-family: 'Nunito'; font-size: 10px; font-weight: 800; color: var(--muted);
  background: rgba(255,255,255,.07); border: 1px solid var(--line); border-bottom-width: 2px;
  border-radius: 5px; padding: 1px 5px; min-width: 18px; text-align: center;
}

/* ================= TITLE ================= */
#title-screen {
  position: absolute; inset: 0; z-index: 50; overflow: hidden;
  background: linear-gradient(#141d3b 0%, #2a3566 30%, #7a5b8f 58%, #f0a06b 78%, #f6c46e 100%);
  display: flex; align-items: center; justify-content: center;
}
.title-sky { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 85%, rgba(255, 214, 140, .45), transparent 55%); }
.title-sun {
  position: absolute; left: 50%; bottom: 22%; width: 34vmin; height: 34vmin; transform: translateX(-50%);
  border-radius: 50%; background: radial-gradient(circle, #fff3c4, #ffd777 45%, rgba(255, 190, 90, 0) 72%);
  filter: blur(1px); animation: sunPulse 7s ease-in-out infinite;
}
@keyframes sunPulse { 0%,100% { transform: translateX(-50%) scale(1); opacity: .95 } 50% { transform: translateX(-50%) scale(1.06); opacity: 1 } }
.title-clouds { position: absolute; inset: 0; overflow: hidden; opacity: .55; }
.title-clouds i {
  position: absolute; width: 260px; height: 46px; border-radius: 999px;
  background: linear-gradient(90deg, rgba(255,255,255,0), rgba(255,235,220,.5), rgba(255,255,255,0));
  filter: blur(8px); animation: drift 60s linear infinite;
}
.title-clouds i:nth-child(1) { top: 12%; left: -20%; animation-duration: 70s; }
.title-clouds i:nth-child(2) { top: 24%; left: -40%; animation-duration: 95s; animation-delay: -30s; width: 380px; }
.title-clouds i:nth-child(3) { top: 6%; left: -60%; animation-duration: 80s; animation-delay: -55s; width: 200px; }
.title-clouds i:nth-child(4) { top: 34%; left: -30%; animation-duration: 110s; animation-delay: -70s; width: 300px; }
@keyframes drift { from { transform: translateX(0) } to { transform: translateX(160vw) } }
.title-hills { position: absolute; left: -10%; right: -10%; bottom: 0; border-radius: 50% 50% 0 0; }
---TAIL---
.starter-card .type-chip { margin: 4px 2px 6px; display: inline-block; }
