@keyframes evoPulse { 0%,100% { transform: scale(1); filter: drop-shadow(0 0 30px rgba(180,150,255,.7)) brightness(1.5) } 50% { transform: scale(1.08); filter: drop-shadow(0 0 60px rgba(220,190,255,1)) brightness(3) } }
.evo-text { font-family: 'Press Start 2P', monospace; font-size: 13px; color: #e5d4ff; margin-top: 20px; }
