.controls-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 7px; margin-top: 8px; }
.control-row { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--muted); font-weight: 700; }
.control-row kbd { min-width: 24px; }

/* dialogue */
#dialogue { position: absolute; inset: 0; z-index: 65; pointer-events: none; display: flex; align-items: flex-end; justify-content: center; padding: 0 16px calc(96px + var(--safe-b)); }
.dlg-box { pointer-events: auto; width: min(860px, 96vw); display: flex; gap: 14px; padding: 14px; border-radius: 18px; border-color: rgba(244,201,93,.3); animation: dlgIn .22s ease-out; }
@keyframes dlgIn { from { opacity: 0; transform: translateY(16px) } to { opacity: 1; transform: none } }
.dlg-portrait { width: 74px; height: 82px; border-radius: 12px; background: radial-gradient(circle at 50% 35%, #3d4f78, #172036); border: 1px solid var(--line); flex: none; overflow: hidden; }
.dlg-portrait canvas { width: 100%; height: 100%; }
.dlg-main { flex: 1; min-width: 0; }
.dlg-name { font-size: 11px; font-weight: 900; color: var(--gold); letter-spacing: .5px; margin-bottom: 3px; }
.dlg-text { font-size: 14px; font-weight: 700; line-height: 1.5; min-height: 42px; }
.dlg-choices { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 10px; }
.dlg-choice { padding: 8px 14px; border-radius: 9px; background: rgba(255,255,255,.07); border: 1px solid var(--line-strong); font-size: 12px; font-weight: 800; }
.dlg-choice:hover { background: rgba(244,201,93,.16); border-color: var(--gold); color: var(--gold-2); }
.dlg-choice.primary { background: rgba(244,201,93,.18); border-color: rgba(244,201,93,.45); color: var(--gold-2); }

#fade { position: absolute; inset: 0; z-index: 80; background: #05080f; opacity: 0; pointer-events: none; transition: opacity .5s; }
#fade.on { opacity: 1; pointer-events: auto; }

/* starter picker */
.starter-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.starter-card {
  position: relative; padding: 16px; border-radius: 16px; text-align: center; border: 1px solid var(--line);
  background: linear-gradient(170deg, rgba(255,255,255,.08), rgba(255,255,255,.02));
  transition: transform .15s, border-color .15s, box-shadow .15s; cursor: pointer;
}
.starter-card:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.starter-card.selected { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(244,201,93,.25), 0 16px 40px rgba(0,0,0,.3); background: linear-gradient(170deg, rgba(244,201,93,.14), rgba(255,255,255,.02)); }
.starter-card img { width: 110px; height: 110px; image-rendering: pixelated; filter: drop-shadow(0 10px 16px rgba(0,0,0,.35)); animation: bob 4s ease-in-out infinite; }
.starter-name { font-size: 17px; font-weight: 900; margin-top: 4px; }
.starter-card .type-chip { margin: 4px 2px 6px; display: inline-block; }
